#!/usr/bin/env python3
"""Backpressure / estimation view of Quent ndjson sessions.
usage: quent_bp.py <session_dir>... [--json out.json]
Per query label (CN labels are '<query id>:<fragment instance id>'; the query id prefix groups fragments) it reports:
  wall, tasks, per-state time (Queued, Routing, Reserving, Preparing, Computing, Finalizing) summed over tasks,
  Reserving requested/peak_estimate vs Computing peak_allocated (memory estimation accuracy),
  data batches: count, bytes, dwell (Stationary -> hop/Destructed), staging leases: count, bytes, held time, InTransit time,
  max concurrent leases, stream hops (relayed/pushed) and scan_split_read statistics.
Sessions from several CNs may be passed together; results are keyed by label and session."""
import sys, os, json, glob, collections
paths = [p for p in sys.argv[1:] if not p.startswith('--')]
jout = sys.argv[sys.argv.index('--json') + 1] if '--json' in sys.argv else None
paths = [p for i, p in enumerate(sys.argv[1:], 1) if not p.startswith('--') and not sys.argv[i - 1].startswith('--')]
# optional: name CN query groups by (query.run) via cnlog_extract.py's json (query_ids are the last 12 chars of the StarRocks query id)
run_of = {}
if '--runs' in sys.argv:
    for run, o in json.load(open(sys.argv[sys.argv.index('--runs') + 1])).items():
        for qid in o.get("query_ids", []): run_of[qid] = run
def name_of(key):
    return run_of.get(key[-12:], key)
def rows(s, kind):
    for f in glob.glob(f"{s}/{kind}/*.ndjson"):
        for l in open(f):
            try: j = json.loads(l)
            except Exception: continue
            yield j
def state(j):
    st = j["data"].get("state", j["data"])
    if isinstance(st, str): return st, {}
    k = next(iter(st)); v = st[k]
    return k, (v if isinstance(v, dict) else {})
import re as _re
def qkey(label):
    if not label: return "unnamed"
    if ":" in label:
        head, tail = label.split(":", 1)
        # CN labels are '<StarRocks query id>:<fragment instance id>' (group by query id); standalone labels are
        # '<tag>:qNN.rK' (group by the full label)
        if _re.fullmatch(r'q\d+\.r\d+', tail): return label
        return head
    return label
out = {}
for s in paths:
    sess = os.path.basename(os.path.normpath(s)); cn = os.path.basename(os.path.dirname(os.path.normpath(s)))
    # queries
    q = {}
    for j in rows(s, "query"):
        k, v = state(j); e = q.setdefault(j["id"], {"t0": j["timestamp"], "t1": j["timestamp"], "label": None, "session_label": None})
        e["t0"] = min(e["t0"], j["timestamp"]); e["t1"] = max(e["t1"], j["timestamp"])
        if k == "Init":
            e["label"] = v.get("query_label") or v.get("instance_name"); e["session_label"] = v.get("session_label")
    plan_q = {}
    for j in rows(s, "plan"):
        k, v = state(j)
        if k == "Declaration": plan_q[j["id"]] = (v.get("parent") or {}).get("query_id")
    pipe = {}
    for j in rows(s, "operator"):
        k, v = state(j)
        if k == "Declaration": pipe[j["id"]] = (plan_q.get(v.get("plan_id")), v.get("instance_name"), v.get("type_name"))
    # scan_split_read statistics live as Statistics records (any dir); collect by executor/pipeline id
    scan_reads = collections.defaultdict(lambda: {"n": 0, "bytes": 0, "ns": 0})
    for d in os.listdir(s):
        if not os.path.isdir(f"{s}/{d}"): continue
        for j in rows(s, d):
            dd = j["data"]
            if isinstance(dd, dict) and "Statistics" in dd:
                attrs = {a["key"]: next(iter(a["value"].values())) for a in dd["Statistics"]["custom_attributes"]}
                if attrs.get("event") == "scan_split_read":
                    qid = plan_q.get(j["id"]) or pipe.get(j["id"], (None,))[0]
                    r = scan_reads[qid]; r["n"] += 1
                    r["bytes"] += int(attrs.get("bytes") or attrs.get("read_bytes") or 0); r["ns"] += int(attrs.get("elapsed_ns") or attrs.get("duration_ns") or 0)
    # tasks
    tasks = collections.defaultdict(list)
    for j in rows(s, "task"):
        k, v = state(j); tasks[j["id"]].append((j["timestamp"], k, v))
    per_q = collections.defaultdict(lambda: {"tasks": 0, "state_s": collections.Counter(), "ops": collections.defaultdict(lambda: [0, 0.0, 0]),
                                             "reserve_req": 0, "reserve_peak_est": 0, "peak_alloc": 0, "input_bytes": 0})
    for tid, ev in tasks.items():
        ev.sort(); pu = next((v["pipeline_uuid"] for _, k, v in ev if k == "Created"), None)
        qid = pipe.get(pu, (None,))[0]; a = per_q[qid]; a["tasks"] += 1
        maxpeak = 0
        for i, (ts, k, v) in enumerate(ev):
            nxt = ev[i + 1][0] if i + 1 < len(ev) else ts; dt = (nxt - ts) / 1e9
            a["state_s"][k] += dt
            if k == "Computing":
                o = a["ops"][v.get("instance_name")]; o[0] += 1; o[1] += dt; o[2] += v.get("input_bytes") or 0
                maxpeak = max(maxpeak, v.get("peak_allocated_bytes") or 0)
            if k == "Reserving":
                a["reserve_req"] += v.get("requested_bytes") or 0; a["reserve_peak_est"] += v.get("peak_estimate") or 0
            if k == "Preparing": a["input_bytes"] += v.get("input_bytes") or 0
        a["peak_alloc"] += maxpeak
    # batches and leases
    by = collections.defaultdict(list)
    for j in rows(s, "data_batch"):
        k, v = state(j); by[j["id"]].append((j["timestamp"], k, v))
    leases = []; batches = []
    for bid, ev in by.items():
        ev.sort(); name = next((v.get("instance_name") for _, k, v in ev if k == "Constructed"), None)
        pu = next((v.get("producer_pipeline_uuid") for _, k, v in ev if k == "Constructed"), None)
        t = {k: ts for ts, k, v in ev}; cap = max((((v.get("memory") or {}).get("capacity") or {}).get("capacity_bytes") or 0) for _, k, v in ev)
        qid_b = pipe.get(pu, (None,))[0]
        if qid_b is None and name == "staging_lease":
            # leases carry no producer pipeline: attribute by time to the query whose span contains the lease start
            tc = t.get("Constructed")
            for qq, info in q.items():
                if tc is not None and info["t0"] - 5e8 <= tc <= info["t1"] + 5e8: qid_b = qq; break
        rec = {"id": bid, "qid": qid_b, "bytes": cap, "t_constructed": t.get("Constructed"), "t_stationary": t.get("Stationary"),
               "t_intransit": t.get("InTransit"), "t_destructed": t.get("Destructed"), "states": [k for _, k, _ in ev]}
        (leases if name == "staging_lease" else batches).append(rec)
    # placements (hops)
    hops = collections.Counter(); hop_bytes = collections.Counter(); hop_batch_t = {}
    for j in rows(s, "batch_placement"):
        k, v = state(j); o = v.get("origin")
        if o and str(o).startswith("stream_"):
            hops[o] += 1; hop_bytes[o] += ((v.get("tier") or {}).get("capacity") or {}).get("capacity_bytes") or 0
            hop_batch_t[v.get("batch_id")] = j["timestamp"]
    # dwell: sink Stationary -> hop placement (local) or InTransit/Destructed
    def dwell(b):
        t0 = b["t_stationary"] or b["t_constructed"]; t1 = b["t_intransit"] or b["t_destructed"]
        return (t1 - t0) / 1e9 if t0 and t1 and t1 >= t0 else None

#!/usr/bin/env python3
"""Map CN cluster.log events to (query, run) using runs.csv start times, then summarize per run:
fragments (role, inputs/outputs, elapsed), declared input stream cardinalities, relayed batches, nixl transmits
(bytes, elapsed/lease/write ms, gbps), failures/cancels. usage: cnlog_extract.py <cluster.log> <runs.csv> [--json out]"""
import re, sys, csv, json, collections, datetime
log, runs = sys.argv[1], sys.argv[2]
jout = sys.argv[sys.argv.index('--json') + 1] if '--json' in sys.argv else None
import glob as _glob
engine_logs = _glob.glob(sys.argv[sys.argv.index('--engine') + 1]) if '--engine' in sys.argv else []
ANSI = re.compile(r'\x1b\[[0-9;]*m')
def ts(s):
    return datetime.datetime.strptime(s[:23], '%Y-%m-%dT%H:%M:%S.%f').replace(tzinfo=datetime.timezone.utc).timestamp()
R = list(csv.DictReader(open(runs)))
windows = []
for i, r in enumerate(R):
    t0 = ts(r['start_utc']); t1 = ts(R[i + 1]['start_utc']) if i + 1 < len(R) else t0 + float(r['ms']) / 1000 + 5
    windows.append((t0, t1, f"{r['query']}.r{r['run']}", r))
def which(t):
    for t0, t1, name, r in windows:
        if t0 - 0.5 <= t < t1: return name
    return None
qid_run = {}; per = collections.defaultdict(lambda: {"fragments": [], "cardinalities": [], "relayed": [], "transmits": [], "failures": [], "cancels": 0, "other_warn": collections.Counter()})
lines = [ANSI.sub('', l) for l in open(log, errors='replace')]
TS = re.compile(r'^(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d+)Z')
for l in lines:
    m = TS.match(l)
    if not m: continue
    t = ts(m.group(1)); q = re.search(r'query_id=(?:Some\(FragmentInstanceId\()?([0-9a-f-]{36})', l)
    if not q: continue
    qid = q.group(1)
    if 'fragment run started' in l:
        run = which(t); qid_run.setdefault(qid, run)
    run = qid_run.get(qid) or which(t)
    if run is None: continue
    p = per[run]
    if 'fragment run started' in l:
        p["fragments"].append({"qid": qid[-12:], "fid": re.search(r'fragment_instance_id=([0-9a-f-]{36})', l).group(1)[-12:], "role": re.search(r'role="(\w+)"', l).group(1),
                               "cn": re.search(r'cn=(\S+)', l).group(1), "inputs": int(re.search(r'inputs=(\d+)', l).group(1)), "outputs": int(re.search(r'outputs=(\d+)', l).group(1)), "t_start": t})
    elif 'fragment run finished' in l or 'fragment run failed' in l:
        fid = re.search(r'fragment_instance_id=([0-9a-f-]{36})', l).group(1)[-12:]
        for f in p["fragments"]:
            if f["fid"] == fid and "elapsed_ms" not in f:
                f["elapsed_ms"] = int(re.search(r'elapsed_ms=(\d+)', l).group(1)); f["status"] = "failed" if 'failed' in l else "ok"
                if 'failed' in l: p["failures"].append(re.search(r'error=(.*)', l).group(1)[:300])
    elif 'declared input stream cardinality' in l:
        p["cardinalities"].append({"fid": re.search(r'fragment_instance_id=([0-9a-f-]{36})', l).group(1)[-12:], "stream": int(re.search(r'stream_id=(\d+)', l).group(1)), "rows": int(re.search(r'rows=(\d+)', l).group(1))})
    elif 'relayed native batches' in l:
        p["relayed"].append({"stream": int(re.search(r'stream_id=(\d+)', l).group(1)), "sender": int(re.search(r'sender_id=(\d+)', l).group(1)), "batches": int(re.search(r'batches=(\d+)', l).group(1))})
    elif 'transmitted batches via nixl' in l:
        g = lambda k: (lambda m: m.group(1) if m else None)(re.search(k + r'="?([0-9.]+)"?', l))
        p["transmits"].append({"stream": g('stream_id'), "sender": g('sender_id'), "dest": (re.search(r'dest=(\S+)', l) or [None, None])[1], "batches": g('batches'), "bytes": g('bytes'), "elapsed_ms": g('elapsed_ms'), "lease_ms": g('lease_ms'), "write_ms": g('write_ms'), "write_gbps": g('write_gbps')})
    elif 'cancel_plan_fragment' in l: p["cancels"] += 1
    elif 'WARN' in l or 'ERROR' in l: p["other_warn"][re.sub(r'[0-9a-f-]{36}|\d+', 'N', l.split(': ', 2)[-1])[:120]] += 1
# engine (C++) logs: "[2026-09-03 13:03:44.795] [warning] [gpu_pipeline_executor.cpp:366] ... reschedule (retry 1/100) ... OOM at operator X"
eng = collections.defaultdict(lambda: {"oom_reschedules": 0, "oom_ops": collections.Counter(), "retry_exhausted": 0, "reservation_failed": 0, "reservation_clamped": 0, "downgrade": 0})
ETS = re.compile(r'^\[(\d{4}-\d\d-\d\d) (\d\d:\d\d:\d\d\.\d+)\]')
for el in engine_logs:
    for l in open(el, errors='replace'):
        m = ETS.match(l)
        if not m: continue
        t = ts(m.group(1) + 'T' + m.group(2)); run = which(t)
        if run is None: continue
        e = eng[run]
        if 'reschedule (retry' in l:
            e["oom_reschedules"] += 1; mo = re.search(r'OOM at operator (\S+)', l); e["oom_ops"][mo.group(1) if mo else '?'] += 1
        elif 'exceeded' in l and 'retries' in l: e["retry_exhausted"] += 1
        elif 'Failed to acquire memory reservation' in l: e["reservation_failed"] += 1
        elif 'clamping reservation request' in l: e["reservation_clamped"] += 1
        elif 'downgrade' in l.lower(): e["downgrade"] += 1
out = {}
for t0, t1, name, r in windows:
    p = per.get(name); 
    if not p: out[name] = {"status": r['status'], "ms": int(r['ms']), "note": "no CN events mapped"}; continue
    frs = p["fragments"]; roles = collections.Counter(f["role"] for f in frs)
    out[name] = {"status": r['status'], "ms": int(r['ms']), "rows": int(r['rows']), "query_ids": sorted({f["qid"] for f in frs}), "fragments": len(frs), "roles": dict(roles),
                 "fragment_ms": sorted(((f["role"], f["cn"], f.get("elapsed_ms")) for f in frs), key=lambda x: -(x[2] or 0))[:12],
                 "declared_cardinalities": p["cardinalities"], "relayed_batches": sum(x["batches"] for x in p["relayed"]), "relayed_streams": len(p["relayed"]),
                 "transmits": p["transmits"], "transmit_bytes": sum(float(x["bytes"] or 0) for x in p["transmits"]), "failures": p["failures"], "cancels": p["cancels"], "warnings": dict(p["other_warn"].most_common(5)),
                 "engine": {"oom_reschedules": eng[name]["oom_reschedules"], "oom_ops": dict(eng[name]["oom_ops"]), "retry_exhausted": eng[name]["retry_exhausted"], "reservation_failed": eng[name]["reservation_failed"], "reservation_clamped": eng[name]["reservation_clamped"], "downgrade_lines": eng[name]["downgrade"]}}
if jout: json.dump(out, open(jout, 'w'), indent=1)
for name, o in out.items():
    if "note" in o: print(f"{name}: {o['status']} {o['ms']}ms  ({o['note']}) oom_reschedules={eng[name]['oom_reschedules']}"); continue
    cards = ', '.join(f"s{c['stream']}={c['rows']:,}" for c in o["declared_cardinalities"][:8])
    tx = f"nixl={len(o['transmits'])} tx_bytes={o['transmit_bytes']/1e9:.2f}GB" if o["transmits"] else ""
    print(f"{name}: {o['status']} {o['ms']}ms frags={o['fragments']} {o['roles']} relayed={o['relayed_batches']}b/{o['relayed_streams']}s {tx} cards[{cards}] slowest={o['fragment_ms'][:3]} fail={len(o['failures'])} cancels={o['cancels']} oom_resched={o['engine']['oom_reschedules']}{('/' + str(o['engine']['oom_ops'])) if o['engine']['oom_reschedules'] else ''} clamped={o['engine']['reservation_clamped']}")
